// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address account, address caller) public {
        vm.assume(account != address(0));
        vm.assume(account != address(this));
        vm.assume(caller != account);
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        bytes32 proposer = c.PROPOSER_ROLE();

        // admin (this contract) grants the role to `account`
        c.grantRole(proposer, account);
        assertTrue(c.hasRole(proposer, account), "precondition: role granted");

        // a third party tries to renounce on behalf of `account`
        vm.prank(caller);
        try c.renounceRole(proposer, account) {
            // even if the call succeeds, a third party must NOT be able to
            // strip another account's role
            assertTrue(c.hasRole(proposer, account), "third party revoked someone else's role");
        } catch {
            // correct contract reverts here; role must be untouched
            assertTrue(c.hasRole(proposer, account), "role changed after revert");
        }
    }
}
